// ⚠️ Nodo de ejemplo. Reemplázalo por la lectura del Excel:
//   Read Binary File → Spreadsheet File (xlsx) → (este nodo).
// Cada item de salida = UNA fila de la asociación grupo-proveedor.
// Columnas del Excel:
//   ID_GRUPO_PROVEEDOR → se busca en groups_prov.external_id  (→ group_id real)
//   ID_PROVEEDOR       → se busca en users.internal_id         (→ provider_id real)
const rows = [
  { row_number: 2, ID_GRUPO_PROVEEDOR: 556, ID_PROVEEDOR: 5231 },
  { row_number: 3, ID_GRUPO_PROVEEDOR: 556, ID_PROVEEDOR: 5232 }
];

return rows.map((r) => ({ json: r }));

// Junta el resultado de todas las filas procesadas en un solo objeto.
// 'matched' = filas que resolvieron ambos ids y se insertaron/actualizaron.
// 'unmatched' = filas donde faltó el grupo o el proveedor (para depurar).
const items = $input.all();
const results = items.map((i) => i.json.result).filter(Boolean);

const matched = results.filter((r) => r.group_provider);
const unmatched = results
  .filter((r) => !r.group_provider)
  .map((r) => r.resolved);

return [{
  json: {
    count: matched.length,
    group_providers: matched.map((r) => r.group_provider),
    unmatched_count: unmatched.length,
    unmatched
  }
}];
